import sys

def lcs(a, b):
    # Bit-parallel LCS (Hyyro): one big-integer step per character of b.
    masks = {}
    for i, ch in enumerate(a):
        masks[ch] = masks.get(ch, 0) | (1 << i)
    full = (1 << len(a)) - 1
    v = full
    for ch in b:
        u = v & masks.get(ch, 0)
        v = ((v + u) | (v - u)) & full
    return len(a) - bin(v).count("1")

lines = sys.stdin.read().split("\n")
if lines and lines[-1] == "":
    lines.pop()
lines = [line.rstrip("\r") for line in lines]
out = []
for k in range(0, len(lines) - 1, 2):
    out.append(str(lcs(lines[k], lines[k + 1])))
