        const long long LIMIT = 5000000;
        long long total = 0;
        bool tooExpensive = false;
        for (size_t t = 0; t < costs.size() && !tooExpensive; t++) {
            long long power = 1;
            for (size_t k = 0; k <= t; k++) {
                power *= costs[t];
                if (power > LIMIT) { tooExpensive = true; break; }
            }
            total += 2 * power;
